import sqlite3


class RepositorioJogadores:
    def __init__(self, con):
        self.con = con

    def adicionar(self, nome, pais=None):
        cur = self.con.execute(
            "INSERT INTO jogadores (nome, pais) VALUES (?, ?)", (nome, pais)
        )
        self.con.commit()
        return cur.lastrowid

    def buscar(self, jogador_id):
        cur = self.con.execute(
            "SELECT id, nome, pais, nivel FROM jogadores WHERE id = ?", (jogador_id,)
        )
        linha = cur.fetchone()
        if linha is None:
            return None
        return self._para_dict(linha)

    def listar(self):
        cur = self.con.execute("SELECT id, nome, pais, nivel FROM jogadores ORDER BY nome")
        return [self._para_dict(linha) for linha in cur.fetchall()]

    def atualizar_nivel(self, jogador_id, nivel):
        cur = self.con.execute(
            "UPDATE jogadores SET nivel = ? WHERE id = ?", (nivel, jogador_id)
        )
        self.con.commit()
        return cur.rowcount > 0

    def remover(self, jogador_id):
        cur = self.con.execute("DELETE FROM jogadores WHERE id = ?", (jogador_id,))
        self.con.commit()
        return cur.rowcount > 0

    def _para_dict(self, linha):
        return {"id": linha[0], "nome": linha[1], "pais": linha[2], "nivel": linha[3]}


