import sqlite3


def id_do_jogador(con, nome):
    """Devolve o id do jogador com esse nome, criando o cadastro se ele for novo."""
    linha = con.execute("SELECT id FROM jogadores WHERE nome = ?", (nome,)).fetchone()
    if linha is not None:
        return linha[0]
    cur = con.execute("INSERT INTO jogadores (nome) VALUES (?)", (nome,))
    return cur.lastrowid


def registrar_partida(con, nome, jogo, pontos, data):
    """Grava uma partida (cadastrando o jogador, se for novo) e devolve o id dela."""
    linha = con.execute("SELECT id FROM jogos WHERE titulo = ?", (jogo,)).fetchone()
    if linha is None:
        raise ValueError(f"Jogo não encontrado: {jogo}")
    jogador_id = id_do_jogador(con, nome)
    cur = con.execute(
        "INSERT INTO partidas (jogador_id, jogo_id, pontos, data) VALUES (?, ?, ?, ?)",
        (jogador_id, linha[0], pontos, data),
    )
    con.commit()
    return cur.lastrowid


def ranking(con, limite=5):
    """Lista (nome, partidas, total) de quem jogou, do maior total para o menor."""
    cur = con.execute(
        """
        SELECT j.nome, COUNT(*) AS partidas, SUM(p.pontos) AS total
        FROM partidas AS p
        JOIN jogadores AS j ON j.id = p.jogador_id
        GROUP BY j.id
        ORDER BY total DESC, j.nome
        LIMIT ?
        """,
        (limite,),
    )
    return cur.fetchall()


def mostrar_ranking(con):
    linhas = ranking(con)
    if not linhas:
        print("Nenhuma partida registrada ainda.")
    for posicao, (nome, partidas, total) in enumerate(linhas, start=1):
        palavra = "partidas"
        if partidas == 1:
            palavra = "partida"
        print(f"{posicao}. {nome} - {total} pontos em {partidas} {palavra}")


def pedir_partida(con):
    nome = input("Jogador: ")
    jogo = input("Jogo: ")
    pontos = input("Pontos: ")
    data = input("Data (AAAA-MM-DD): ")
    if not pontos.isdigit():
        print("Os pontos precisam ser um número inteiro.")
        return
    try:
        registrar_partida(con, nome, jogo, int(pontos), data)
        print("Partida registrada.")
    except ValueError as erro:
        print(erro)


def main():
    con = sqlite3.connect("jogo.db")
    con.execute("PRAGMA foreign_keys = ON")
    print("1 - Registrar partida")
    print("2 - Ver ranking")
    print("0 - Sair")
    while True:
        opcao = input("Escolha: ")
        if opcao == "1":
            pedir_partida(con)
        elif opcao == "2":
            mostrar_ranking(con)
        elif opcao == "0":
            break
        else:
            print("Opção inválida.")
    con.close()


if __name__ == "__main__":
    main()
